package com.sami.app.purchasing.web; import com.sami.app.common.api.ApiResponse; import com.sami.app.purchasing.service.PurchaseOrderService; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/purchase-orders") @RequiredArgsConstructor public class PurchaseOrderController{private final PurchaseOrderService service;@PostMapping @PreAuthorize("@authz.has('purchasing:create')") public ApiResponse<Map<String,Object>> create(@RequestParam Long companyId,@RequestParam Long branchId,@RequestParam Long supplierId,@RequestBody List<Map<String,Object>> lines,@RequestParam(required=false) String notes){return ApiResponse.ok(service.create(companyId,branchId,supplierId,lines,notes));}@PostMapping("/{id}/submit") @PreAuthorize("@authz.has('purchasing:edit')") public ApiResponse<Void> submit(@PathVariable Long id){service.submit(id);return ApiResponse.ok(null);}@PostMapping("/{id}/approve") @PreAuthorize("@authz.has('purchasing:approve')") public ApiResponse<Void> approve(@PathVariable Long id){service.approve(id);return ApiResponse.ok(null);}@PostMapping("/{id}/cancel") @PreAuthorize("@authz.has('purchasing:cancel')") public ApiResponse<Void> cancel(@PathVariable Long id){service.cancel(id);return ApiResponse.ok(null);}}
